{"packet_id":"R004-01","doc_id":"R004","jurisdiction":"Hoboken, NJ","category":"screening_restrictions","lifecycle":"enacted","title":"Hoboken Tenant Fair Chance Ordinance criminal history screening limits","requirement":"A landlord may not ask about an applicant's criminal history before making a conditional offer. After a conditional offer, the landlord may consider only convictions from the past five years and must give the applicant a chance to explain.","key_value":"5 years","coverage_conditions":"All residential rental units in Hoboken, except owner-occupied buildings with four or fewer units.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":true,"other":"Exempts owner-occupied buildings with four or fewer units"},"exemptions":"Owner-occupied buildings with four or fewer units.","penalty":"Board may fine a landlord up to $2,000 for each violation; tenant may file a complaint with the Board within one year.","effective_date":"2026-03-01","citation":"Hoboken Tenant Fair Chance Ordinance","quoted_span":"A landlord may not ask about an applicant's criminal history before making a conditional offer. After a conditional offer, a landlord may consider only convictions from the past five years and must give the applicant a chance to explain.","interaction":null,"confidence":0.75,"conflict_flag":false,"conflict_note":null}
